use std::path::PathBuf;
use ingetrazo_core::camera::OrbitCamera;
use ingetrazo_render::vector_hlr::LineKind;
fn main(){let args:Vec<_>=std::env::args_os().collect();if args.get(1).is_some_and(|a|a=="--hlr-worker"){ingetrazo_render::process_hlr::worker_main(std::path::Path::new(&args[2])).unwrap();return;}let mut pool=ingetrazo_render::process_hlr::HlrProcessPool::new(&std::env::current_exe().unwrap(),2,64,8*1024*1024).unwrap();let root=PathBuf::from(std::env::args().nth(1).expect("fixture directory"));for entry in std::fs::read_dir(&root).unwrap(){let path=entry.unwrap().path();if !path.to_string_lossy().ends_with(".reference.json"){continue;}let reference:serde_json::Value=serde_json::from_slice(&std::fs::read(&path).unwrap()).unwrap();let name=reference["name"].as_str().unwrap();let scene=ingetrazo_formats::igz::load_igz(&root.join(format!("{name}.igz"))).unwrap();let camera:OrbitCamera=serde_json::from_value(reference["camera"].clone()).unwrap();for hidden in [false,true] { let result=ingetrazo_render::vector_hlr::parallel_segments_with_pool(&scene,&camera,true,hidden,&mut pool).unwrap();let world=result.iter().map(|s|[s.a.to_array(),s.b.to_array()]).collect::<Vec<_>>();let kinds=result.iter().map(|s|match s.kind{LineKind::Edge=>0,LineKind::Profile=>1,LineKind::Cut=>2,LineKind::Hidden=>3}).collect::<Vec<_>>();std::fs::write(root.join(format!("{name}.{}.rust.json",hidden)),serde_json::to_vec_pretty(&serde_json::json!({"world":world,"kinds":kinds,"cap_triangles":ingetrazo_render::vector_hlr::paper_section_triangles(&scene).iter().map(|t|t.iter().map(|p|{let q=camera.view_matrix().transform_point3(*p);[q.x,q.y]}).collect::<Vec<_>>()).collect::<Vec<_>>()})).unwrap()).unwrap();}}}
